<?php
declare(strict_types=1);

/** Singleton PDO wrapper. Reads config/database.php (regenerated by the installer). */
class Database
{
    private static ?Database $instance = null;
    private PDO $connection;

    private function __construct()
    {
        $config = require CONFIG_PATH . '/database.php';
        $dsn = sprintf(
            '%s:host=%s;port=%d;dbname=%s;charset=%s',
            $config['driver'],
            $config['host'],
            $config['port'],
            $config['database'],
            $config['charset']
        );
        $this->connection = new PDO($dsn, $config['username'], $config['password'], [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            // Use client-side emulated prepares: avoids MySQL/MariaDB error 1615
            // ("Prepared statement needs to be re-prepared") on shared hosts where
            // the server-side statement cache is small and evicts statements
            // between prepare() and execute(). PDO quotes values itself, so this
            // is still injection-safe and is PDO's default mode.
            PDO::ATTR_EMULATE_PREPARES => true,
            PDO::MYSQL_ATTR_USE_BUFFERED_QUERY => true,
        ]);
    }

    public static function getInstance(): self
    {
        if (self::$instance === null) {
            self::$instance = new self();
        }
        return self::$instance;
    }

    /**
     * True only when config/database.php exists with credentials that can actually
     * connect. Used at boot to detect a "new environment": a lock file copied from
     * another machine (or rotated credentials) must not make the app believe it is
     * installed and then crash with a raw PDOException on the first page load.
     */
    public static function isReachable(): bool
    {
        $configFile = CONFIG_PATH . '/database.php';
        if (!is_file($configFile)) {
            return false;
        }
        try {
            $config = require $configFile;
            if (empty($config['host']) || empty($config['database']) || empty($config['username'])) {
                return false;
            }
            $dsn = sprintf(
                '%s:host=%s;port=%d;dbname=%s;charset=%s',
                $config['driver'] ?? 'mysql',
                $config['host'],
                $config['port'] ?? 3306,
                $config['database'],
                $config['charset'] ?? 'utf8mb4'
            );
            $pdo = new PDO($dsn, $config['username'], $config['password'] ?? '', [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_TIMEOUT => 3,
            ]);
            $pdo->query('SELECT 1');
            return true;
        } catch (Throwable $e) {
            return false;
        }
    }

    /**
     * True when an arbitrary PDO points at a database that already contains the
     * app's signature tables (i.e. a completed install). Used to tell "fresh
     * install" from "reconnect to an existing site" so updates never lose data.
     */
    public static function databaseHasSchema(PDO $pdo): bool
    {
        try {
            foreach (['settings', 'users', 'media_posts', 'org_units', 'forms'] as $table) {
                $stmt = $pdo->prepare('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ?');
                $stmt->execute([$table]);
                if ((int) $stmt->fetchColumn() === 0) {
                    return false;
                }
            }
            // Check that at least one admin/user exists to consider it a fully initialized existing install
            $stmt = $pdo->query('SELECT COUNT(*) FROM users');
            if ((int) $stmt->fetchColumn() === 0) {
                return false;
            }
            return true;
        } catch (Throwable $e) {
            return false;
        }
    }

    /** True when the configured database is reachable AND already has the app schema. */
    public static function hasAppSchema(): bool
    {
        if (!self::isReachable()) {
            return false;
        }
        try {
            return self::databaseHasSchema(self::getInstance()->getConnection());
        } catch (Throwable $e) {
            return false;
        }
    }

    public function getConnection(): PDO
    {
        return $this->connection;
    }

    /**
     * Runs idempotent in-place migrations for already-installed databases
     * (the installer only applies schema.sql once, so later feature columns
     * must be added here). Each migration runs at most once and the result is
     * stamped to storage/migrations.json. Failures are logged, never fatal.
     */
    public static function migrate(): void
    {
        try {
            $pdo = self::getInstance()->getConnection();

            // Self-healing: Apply idempotent schema.sql to automatically create any
            // missing core tables or default seed pages (e.g. privacy-policy, about).
            try {
                self::importSqlFile($pdo, INSTALLER_PATH . '/schema.sql');
            } catch (Throwable $e) {
                error_log('Schema import auto-heal notice: ' . $e->getMessage());
            }

            $stampFile = STORAGE_PATH . '/migrations.json';
            $done = [];
            if (is_file($stampFile)) {
                $decoded = json_decode((string) file_get_contents($stampFile), true);
                $done = is_array($decoded) ? $decoded : [];
            }
            foreach (self::migrations() as $name => $fn) {
                try {
                    $fn($pdo);
                } catch (Throwable $e) {
                    error_log('Migration ' . $name . ' auto-heal notice: ' . $e->getMessage());
                }
                if (!in_array($name, $done, true)) {
                    $done[] = $name;
                }
            }
            @file_put_contents($stampFile, json_encode($done));
        } catch (Throwable $e) {
            error_log('Database::migrate skipped: ' . $e->getMessage());
        }
    }

