                // Floating "Get it on Google Play" button on the public website.
                // app_download_pages: 'all' or a comma-separated list of paths.
                self::addColumnIfMissing($pdo, 'settings', 'app_download_enabled', "TINYINT(1) NOT NULL DEFAULT 0", 'giving_url');
                self::addColumnIfMissing($pdo, 'settings', 'app_download_url', 'VARCHAR(500) NULL', 'app_download_enabled');
                self::addColumnIfMissing($pdo, 'settings', 'app_download_pages', 'TEXT NULL', 'app_download_url');
            },
            '2026_08_attendance' => function (PDO $pdo): void {
                // Church growth tracking: attendance records + newcomer follow-up.
                $pdo->exec("CREATE TABLE IF NOT EXISTS `attendance_records` (
                    `id` INT AUTO_INCREMENT PRIMARY KEY,
                    `org_unit_id` INT NULL,
                    `service_date` DATE NOT NULL,
                    `service_name` VARCHAR(120) NOT NULL,
                    `topic` VARCHAR(255) NULL,
                    `bible_text` VARCHAR(255) NULL,
                    `male_count` INT NOT NULL DEFAULT 0,
                    `female_count` INT NOT NULL DEFAULT 0,
                    `notes` TEXT NULL,
                    `created_by` INT NULL,
                    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                    INDEX `idx_attendance_unit_date` (`org_unit_id`, `service_date`),
                    FOREIGN KEY (`org_unit_id`) REFERENCES `org_units`(`id`) ON DELETE SET NULL
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
                $pdo->exec("CREATE TABLE IF NOT EXISTS `newcomers` (
                    `id` INT AUTO_INCREMENT PRIMARY KEY,
                    `org_unit_id` INT NULL,
                    `name` VARCHAR(150) NOT NULL,
                    `whatsapp_phone` VARCHAR(40) NULL,
                    `address` VARCHAR(255) NULL,
                    `gender` ENUM('male','female','other') NULL,
                    `age_group` ENUM('adult','children','youth') NOT NULL DEFAULT 'adult',
                    `attendance_id` INT NULL,
                    `visit_date` DATE NULL,
                    `follow_up_status` ENUM('new','contacted','followed_up','returned','inactive') NOT NULL DEFAULT 'new',
                    `notes` TEXT NULL,
                    `created_by` INT NULL,
                    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                    INDEX `idx_newcomer_unit_status` (`org_unit_id`, `follow_up_status`),
                    FOREIGN KEY (`org_unit_id`) REFERENCES `org_units`(`id`) ON DELETE SET NULL,
                    FOREIGN KEY (`attendance_id`) REFERENCES `attendance_records`(`id`) ON DELETE SET NULL
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
            },
            '2026_08_backfill_media_units' => function (PDO $pdo): void {
                // Posts created before the org hierarchy existed (or by an admin
                // with no home unit) have org_unit_id = NULL and therefore never
                // show up on any church's unit page. Assign them to the super
                // admin's home unit when set, otherwise to the first parish, so
                // they become visible and can be moved with the Church control.
                $nullCount = (int) $pdo->query('SELECT COUNT(*) FROM media_posts WHERE org_unit_id IS NULL')->fetchColumn();
                if ($nullCount === 0) {
                    return;
                }
                $target = (int) $pdo->query("SELECT org_unit_id FROM users WHERE is_super_admin = 1 AND org_unit_id IS NOT NULL ORDER BY id ASC LIMIT 1")->fetchColumn();
                if ($target <= 0) {
                    $target = (int) $pdo->query("SELECT id FROM org_units WHERE type = 'parish' ORDER BY id ASC LIMIT 1")->fetchColumn();
                }
                if ($target > 0) {
                    $pdo->prepare('UPDATE media_posts SET org_unit_id = ? WHERE org_unit_id IS NULL')->execute([$target]);
                }
            },
            '2026_08_pinned_reels' => function (PDO $pdo): void {
                // Pin reels so they always surface first. Up to 3 active pins per
                // church (org_unit_id); each pin auto-expires after 3 days. The
                // effective pin check everywhere is:
                //   is_pinned = 1 AND pinned_expires_at > NOW()
                self::addColumnIfMissing($pdo, 'media_posts', 'is_pinned', "TINYINT(1) NOT NULL DEFAULT 0", 'org_unit_id');
                self::addColumnIfMissing($pdo, 'media_posts', 'pinned_at', 'DATETIME NULL', 'is_pinned');
                self::addColumnIfMissing($pdo, 'media_posts', 'pinned_expires_at', 'DATETIME NULL', 'pinned_at');
            },
            '2026_08_app_redirect' => function (PDO $pdo): void {
                // "Admin & App only" mode: when enabled, Android phone visitors
                // are sent to the app. 'interstitial' shows a landing page with a
                // Google Play button + a "Continue to website" escape (remembered
                // per browser); 'force' redirects straight to the Play link.
                self::addColumnIfMissing($pdo, 'settings', 'app_redirect_mode', "VARCHAR(12) NOT NULL DEFAULT 'off'", 'app_download_pages');
            },
            '2026_08_attendance_gender' => function (PDO $pdo): void {
                // Attendance now tracks the Youth church by gender (male/female)
                // instead of the whole-church adult/children/youth split. The old
                // columns are left in place (harmless, unused) so the migration
                // never destroys existing data.
                self::addColumnIfMissing($pdo, 'attendance_records', 'male_count', 'INT NOT NULL DEFAULT 0', 'bible_text');
                self::addColumnIfMissing($pdo, 'attendance_records', 'female_count', 'INT NOT NULL DEFAULT 0', 'male_count');
            },
            '2026_08_form_cascade_church' => function (PDO $pdo): void {
                // Form fields now support cascading dropdowns (Province > Zone >
                // Area > Parish) and an auto church-list field that builds the
                // same chained selects live from the org_units hierarchy.
                $pdo->exec("ALTER TABLE `form_fields` MODIFY COLUMN `field_type` ENUM('text','textarea','email','phone','number','date','url','select','radio','checkbox','image','cascade','church') NOT NULL DEFAULT 'text'");
            },
            '2026_08_export_files' => function (PDO $pdo): void {
                // Server-hosted shareable CSV exports (Google-Forms style): each
                // export is saved to storage/exports and exposed via an
                // unguessable /export/{token} link that anyone with the link can
                // view or download. Admins generate/remove these from the panel.
                $pdo->exec("CREATE TABLE IF NOT EXISTS `export_files` (
                    `id` INT AUTO_INCREMENT PRIMARY KEY,
                    `kind` VARCHAR(40) NOT NULL DEFAULT 'csv',
                    `title` VARCHAR(255) NULL,
                    `filename` VARCHAR(255) NOT NULL,
                    `token` VARCHAR(64) NOT NULL UNIQUE,
                    `path` VARCHAR(255) NOT NULL,
                    `form_id` INT NULL,
                    `created_by` INT NULL,
                    `downloads` INT NOT NULL DEFAULT 0,
                    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (`form_id`) REFERENCES `forms`(`id`) ON DELETE CASCADE,
                    FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON DELETE SET NULL,
                    INDEX `idx_export_form` (`form_id`)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
            },
            '2026_08_form_visibility' => function (PDO $pdo): void {
                // Forms can now be public (anyone with the link) or private
                // (link + password). password_hash is only used when private.
                self::addColumnIfMissing($pdo, 'forms', 'visibility', "ENUM('public','private') NOT NULL DEFAULT 'public'", 'is_active');
                self::addColumnIfMissing($pdo, 'forms', 'password_hash', 'VARCHAR(255) NULL', 'visibility');
            },
            '2026_08_form_datetime_fields' => function (PDO $pdo): void {
                // New form field types: 'time' and 'datetime' (date and time).
                $pdo->exec("ALTER TABLE `form_fields` MODIFY COLUMN `field_type` ENUM('text','textarea','email','phone','number','date','url','select','radio','checkbox','image','cascade','church','time','datetime') NOT NULL DEFAULT 'text'");
            },
            '2026_08_church_registration' => function (PDO $pdo): void {
                // Public church-admin self-registration, pending super-admin approval.
                $pdo->exec("CREATE TABLE IF NOT EXISTS `pending_registrations` (
                    `id` INT AUTO_INCREMENT PRIMARY KEY,
                    `name` VARCHAR(150) NOT NULL,
                    `email` VARCHAR(150) NOT NULL,
                    `phone` VARCHAR(45) NULL,
                    `username` VARCHAR(100) NOT NULL,
                    `password_hash` VARCHAR(255) NOT NULL,
                    `province_id` INT NULL,
                    `zone_id` INT NULL,
                    `area_id` INT NULL,
                    `parish_name` VARCHAR(150) NULL,
                    `parish_id` INT NULL,
                    `status` ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
                    `reviewed_by` INT NULL,
                    `reviewed_at` TIMESTAMP NULL,
                    `reject_reason` VARCHAR(500) NULL,
                    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (`province_id`) REFERENCES `org_units`(`id`) ON DELETE SET NULL,
                    FOREIGN KEY (`zone_id`) REFERENCES `org_units`(`id`) ON DELETE SET NULL,
                    FOREIGN KEY (`area_id`) REFERENCES `org_units`(`id`) ON DELETE SET NULL,
                    FOREIGN KEY (`parish_id`) REFERENCES `org_units`(`id`) ON DELETE SET NULL,
                    INDEX `idx_reg_status` (`status`, `created_at`)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

                // Publicly-flagged church name corrections, approved/rejected by the super admin.
                $pdo->exec("CREATE TABLE IF NOT EXISTS `church_name_flags` (
                    `id` INT AUTO_INCREMENT PRIMARY KEY,
                    `org_unit_id` INT NULL,
                    `current_name` VARCHAR(150) NOT NULL,
                    `suggested_name` VARCHAR(150) NOT NULL,
                    `status` ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
                    `reported_by` VARCHAR(150) NULL,
                    `reviewed_by` INT NULL,
                    `reviewed_at` TIMESTAMP NULL,
                    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (`org_unit_id`) REFERENCES `org_units`(`id`) ON DELETE SET NULL,
                    FOREIGN KEY (`reviewed_by`) REFERENCES `users`(`id`) ON DELETE SET NULL,
                    INDEX `idx_flag_status` (`status`, `created_at`)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

                // All church names are stored in CAPS.
                $pdo->exec('UPDATE org_units SET name = UPPER(name)');
            },
