            // ⚠️ **The column that makes a PayHub payment findable, and the reason a live one was not.**
            //
            // PayHub's `api/transaction/initialize` **ignores the reference we send** and mints its own
            // `PH_<hex>` one. So the money is recorded at the gateway against a reference this application
            // had never stored anywhere — while every later question (the return URL, the webhook, the
            // retry) was asked with *our* reference, which PayHub has never heard of. The gateway's answer
            // to that is "The reference not found", which is exactly what the advertiser was shown after
            // paying. The working PayHub integration this was checked against says the same thing in its own
            // comments: *"Verify against a local reference would return Transaction not found."*
            //
            // `reference` stays the attempt's identity — it is the credential in the advertiser's URL and
            // the thing the retry counter is keyed on — and this column holds the gateway's own reference
            // beside it. Verifying asks the gateway about THIS one.
            //
            // `donations` gets it too, because online giving goes through the same gateway and had the same
            // hole: a giver could pay and the gift would sit at `pending` for ever.
            '2026_46_payhub_gateway_reference' => function (PDO $pdo): void {
                self::addColumnIfMissing($pdo, 'ad_payments', 'gateway_reference', 'VARCHAR(120) NULL', 'reference');
                self::addIndexIfMissing($pdo, 'ad_payments', 'idx_ad_payment_gateway_ref', 'INDEX `idx_ad_payment_gateway_ref` (`gateway_reference`)');

                self::addColumnIfMissing($pdo, 'donations', 'gateway_reference', 'VARCHAR(120) NULL', 'payment_reference');
                self::addIndexIfMissing($pdo, 'donations', 'idx_donation_gateway_ref', 'INDEX `idx_donation_gateway_ref` (`gateway_reference`)');
            },
        ];
    }

    private static function addColumnIfMissing(PDO $pdo, string $table, string $column, string $definition, ?string $after): void
    {
        $check = $pdo->prepare('SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ?');
        $check->execute([$table, $column]);
        if ((int) $check->fetchColumn() > 0) {
            return;
        }
        $sql = 'ALTER TABLE `' . $table . '` ADD COLUMN `' . $column . '` ' . $definition;
        if ($after) {
            $sql .= ' AFTER `' . $after . '`';
        }
        $pdo->exec($sql);
    }

    /**
     * Drops a column, but only when it is actually there.
     *
     * Migrations run on every bootstrap, so an unguarded ALTER TABLE would take the whole site
     * down the second time it ran. Same reasoning as addColumnIfMissing, and the guard is what
     * makes a destructive step safe to leave in place forever.
     */
    private static function dropColumnIfExists(PDO $pdo, string $table, string $column): void
    {
        $check = $pdo->prepare('SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ?');
        $check->execute([$table, $column]);
        if ((int) $check->fetchColumn() === 0) {
            return;
        }
        $pdo->exec('ALTER TABLE `' . $table . '` DROP COLUMN `' . $column . '`');
    }

    /** Adds an index (or unique key) when no index of that name already exists. */
    private static function addIndexIfMissing(PDO $pdo, string $table, string $indexName, string $definition): void
    {
        $check = $pdo->prepare('SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND INDEX_NAME = ?');
        $check->execute([$table, $indexName]);
        if ((int) $check->fetchColumn() > 0) {
            return;
        }
        $pdo->exec('ALTER TABLE `' . $table . '` ADD ' . $definition);
    }

    private static function addForeignKeyIfMissing(PDO $pdo, string $table, string $constraint, string $column, string $refTable, string $refColumn, string $onDelete): void
    {
        $check = $pdo->prepare('SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = ? AND CONSTRAINT_NAME = ?');
        $check->execute([$table, $constraint]);
        if ((int) $check->fetchColumn() > 0) {
            return;
        }
        $pdo->exec("ALTER TABLE `{$table}` ADD CONSTRAINT `{$constraint}` FOREIGN KEY (`{$column}`) REFERENCES `{$refTable}`(`{$refColumn}`) ON DELETE {$onDelete}");
    }

    /** Builds a fresh PDO from arbitrary credentials without touching the singleton — used by the installer. */
    public static function testConnection(string $host, int $port, string $database, string $username, string $password): PDO
    {
        $dsn = sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4', $host, $port, $database);
        return new PDO($dsn, $username, $password, [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            PDO::MYSQL_ATTR_USE_BUFFERED_QUERY => true,
        ]);
    }

    /**
     * Naive but sufficient statement splitter for our own schema.sql. Splits on
     * ';' outside of string literals and backticks, so semicolons inside column
     * COMMENTS and seeded data can't break the import.
     */
    public static function importSqlFile(PDO $pdo, string $path): void
    {
        $sql = (string) file_get_contents($path);
        $sql = preg_replace('/^--.*$/m', '', $sql); // strip line comments
        foreach (self::splitStatements($sql) as $statement) {
            // query()+fetchAll() consumes any result set (e.g. an EXECUTE of a
            // SELECT) so the next statement never trips MySQL's "unbuffered
            // query active" (SQLSTATE 2014) error.
            $pdo->query($statement)->fetchAll();
        }
    }

    /**
     * Splits SQL into statements, honouring '...', "..." and `...` with '' / "" / `` / \\ escapes.
     *
     * The double quote is a string delimiter in MySQL's default mode, and this did not honour it: it
     * tracked only `'` and the backtick. The failure that exposed it was a `COMMENT "The church's own bank
     * details, …"` — one apostrophe inside double quotes, which left the scanner inside a string for the
     * rest of the file and produced a syntax error pointing at a column sixty-six lines further down.
     *
     * The reason the same construct already existed and worked (`COMMENT "'all' or comma-separated page
     * paths"`) is luck rather than correctness: it contains TWO apostrophes, so the toggling cancelled out.
     * An odd number of them — which is what ordinary prose produces — broke it. A permanent tool should not
     * depend on that.
     */
    private static function splitStatements(string $sql): array
    {
        $statements = [];
        $buffer = '';
        $length = strlen($sql);
        $quote = null;
        for ($i = 0; $i < $length; $i++) {
            $char = $sql[$i];
            if ($quote !== null) {
                $buffer .= $char;
                if ($char === $quote) {
                    // MySQL escapes a quote inside a string by doubling it ('' or ``)
                    if ($i + 1 < $length && $sql[$i + 1] === $quote) {
                        $buffer .= $sql[$i + 1];
                        $i++;
                    } else {
                        $quote = null;
                    }
                } elseif ($char === '\\' && $i + 1 < $length) {
                    $buffer .= $sql[$i + 1];
                    $i++;
                }
                continue;
            }
            if ($char === "'" || $char === '"' || $char === '`') {
                $quote = $char;
                $buffer .= $char;
                continue;
            }
            if ($char === ';') {
                $trimmed = trim($buffer);
                if ($trimmed !== '') {
                    $statements[] = $trimmed;
                }
                $buffer = '';
                continue;
            }
            $buffer .= $char;
        }
        $trimmed = trim($buffer);
        if ($trimmed !== '') {
            $statements[] = $trimmed;
        }
        return $statements;
    }
}
